cat > /tmp/probe/brute.sh <<'SH'
#!/bin/bash
D=$(mktemp -d)
python3 - <<'PY' > /tmp/probe/cand.txt
import string
cs=string.ascii_lowercase
for a in cs:
  for b in cs:
    for c in cs:
      print(a+b+c)
for a in cs:
  for b in cs:
    for c in cs:
      for d in cs:
        print(a+b+c+d)
PY
: > /tmp/probe/accepted.txt
while read -r v; do
  if _ZO_DATA_DIR=$D /workspace/executable import --from="$v" /dev/null >/dev/null 2>&1; then echo "$v" >> /tmp/probe/accepted.txt; fi
done < /tmp/probe/cand.txt
echo "DONE" >> /tmp/probe/accepted.txt
SH
chmod +x /tmp/probe/brute.sh
/tmp/probe/brute.sh
